\set ON_ERROR_STOP 1
\pset format unaligned
\pset tuples_only on
create temp table r(step serial, label text, val text);
create temp table ids(k text primary key, v text);
insert into auth.users(id,email) values ('aaaaaaaa-0000-0000-0000-000000000001','pilot-creator@linkup.test'),('aaaaaaaa-0000-0000-0000-000000000002','pilot-referrer@linkup.test'),('aaaaaaaa-0000-0000-0000-000000000003','staff@heleni.test');
grant select, insert, update on ids, r to authenticated; grant usage on sequence r_step_seq to authenticated;
-- referrer + creator joining through referral link
select set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000002',false); set role authenticated;
insert into ids values ('referrer', public.create_organization('creator','Pilot Referrer')::text); reset role;
insert into ids values ('refcode', (select referral_code from organizations where id=(select v::uuid from ids where k='referrer')));
select set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000001',false); set role authenticated;
insert into ids values ('creator', public.create_organization('creator','Pilot Creator',null,(select v from ids where k='refcode'))::text); reset role;
insert into r(label,val) select 'referral link → referral', program||'/'||status||'/'||reward_bps from referrals where referred_org_id=(select v::uuid from ids where k='creator');
-- store owner publishes offer
select set_config('request.jwt.claim.sub','737ca9c9-fc97-446b-a65c-acf78a343d19',false); set role authenticated;
insert into ids values ('opp', public.save_standing_opportunity('9f589a3a-4a03-4b70-a8e4-921ba175d11d','Heleni Jewelry','תכשיטים בעבודת יד',1000,10,true,'live')::text);
insert into r(label,val) select 'store: next action after offer', case when (public.org_status('9f589a3a-4a03-4b70-a8e4-921ba175d11d')->>'standing_live')::boolean then 'offer live' else 'FAIL' end;
do $$ begin perform public.join_opportunity((select v::uuid from ids where k='opp'),'2189c35e-bfa0-48e3-b2ef-e858a1f9968e'); insert into r(label,val) values ('self-deal blocked','FAIL'); exception when others then insert into r(label,val) values ('self-deal blocked',sqlerrm); end $$;
reset role;
-- products from plugin 0.3.0 payload (generated by the PHP harness)
select public.plugin_sync_products('100432dd-d061-4aa7-8eab-565f20f53edf', pg_read_file('/var/tmp/lkpg/products.json')::jsonb);
insert into r(label,val) select 'products synced', count(*)||' active, '||count(*) filter (where in_stock)||' in stock' from products where status='active';
-- creator: catalog → join → code
select set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000001',false); set role authenticated;
insert into r(label,val) select 'catalog shows Heleni with products', (select x->>'store_name'||' / '||json_array_length(x->'products')||' products' from json_array_elements(public.catalog()) x where x->>'store_name'='Heleni Jewelry');
insert into ids values ('code', public.join_opportunity((select v::uuid from ids where k='opp'),(select v::uuid from ids where k='creator'))->>'code');
insert into r(label,val) select 'creator coupon + link', v||'  /r/'||v from ids where k='code';
insert into r(label,val) select 'partner link resolves', (public.resolve_partner_link((select v from ids where k='code'))::jsonb->>'site_url');
reset role;
-- sale with coupon (plugin 0.2.1 payload, VAT-inclusive store, tax=0), completed 20 days ago
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p1','occurred_at',(now()-interval '20 days')::text,'order',jsonb_build_object('id','PILOT-1','status','completed','currency','ILS','total',11800,'tax',0,'shipping',0,'shipping_tax',0,'coupons',jsonb_build_array(lower((select v from ids where k='code'))),'refunds','[]'::jsonb,'ref','','email_hash','','created_at',now()::text)));
insert into r(label,val) select 'sale ₪118 attributed', a.method||', base '||o.base_minor||', creator '||a.commission_bps||'bps, LINKUP '||a.platform_fee_bps||'bps' from attributions a join orders o on o.id=a.order_id where o.external_order_id='PILOT-1';
insert into r(label,val) select 'commission / LINKUP fee', string_agg(party_role||'='||amount_minor, ' ' order by party_role) from commission_ledger l join attributions a on a.id=l.attribution_id join orders o on o.id=a.order_id where o.external_order_id='PILOT-1';
-- sale via link (no coupon)
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p1b','occurred_at',(now()-interval '20 days')::text,'order',jsonb_build_object('id','PILOT-L','status','completed','currency','ILS','total',23600,'tax',0,'shipping',0,'shipping_tax',0,'coupons','[]'::jsonb,'refunds','[]'::jsonb,'ref',(select v from ids where k='code')||'|'||extract(epoch from now()-interval '1 hour')::bigint,'email_hash','','created_at',now()::text)));
insert into r(label,val) select 'sale via link attributed', a.method||', creator='||(select sum(amount_minor) from commission_ledger where attribution_id=a.id and party_role='creator') from attributions a join orders o on o.id=a.order_id where o.external_order_id='PILOT-L';
-- partial refund ₪59
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p2','occurred_at',(now()-interval '19 days')::text,'order',jsonb_build_object('id','PILOT-1','status','completed','currency','ILS','total',11800,'tax',0,'shipping',0,'shipping_tax',0,'coupons',jsonb_build_array(lower((select v from ids where k='code'))),'refunds',jsonb_build_array(jsonb_build_object('id','rf1','amount',5900)),'ref','','email_hash','','created_at',now()::text)));
insert into r(label,val) select 'after ₪59 refund', string_agg(party_role||'='||s, ' ' order by party_role) from (select party_role, sum(amount_minor) s from commission_ledger l join attributions a on a.id=l.attribution_id join orders o on o.id=a.order_id where o.external_order_id='PILOT-1' group by 1) x;
-- cancellation
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p3','occurred_at',now()::text,'order',jsonb_build_object('id','PILOT-2','status','processing','currency','ILS','total',23600,'tax',0,'shipping',0,'shipping_tax',0,'coupons',jsonb_build_array((select v from ids where k='code')),'refunds','[]'::jsonb,'ref','','email_hash','','created_at',now()::text)));
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p4','occurred_at',(now()+interval '1 second')::text,'order',jsonb_build_object('id','PILOT-2','status','cancelled','currency','ILS','total',23600,'tax',0,'shipping',0,'shipping_tax',0,'coupons',jsonb_build_array((select v from ids where k='code')),'refunds','[]'::jsonb,'ref','','email_hash','','created_at',now()::text)));
insert into r(label,val) select 'cancelled order net', coalesce(sum(amount_minor),0)::text from commission_ledger l join attributions a on a.id=l.attribution_id join orders o on o.id=a.order_id where o.external_order_id='PILOT-2';
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p4','occurred_at',now()::text,'order',jsonb_build_object('id','PILOT-2','status','cancelled','currency','ILS','total',23600)));
insert into r(label,val) values ('duplicate event ignored', 'ok');
-- approval → monthly request (test mode) → paid → referral reward
insert into r(label,val) select 'approved after 14 days', public.approve_matured_commissions()::text||' lines';
set session_replication_role = replica; update commission_ledger set approved_at = date_trunc('month', now()) - interval '10 days' where state='approved' and store_org_id='9f589a3a-4a03-4b70-a8e4-921ba175d11d'; set session_replication_role = origin;
select set_config('request.jwt.claim.sub','737ca9c9-fc97-446b-a65c-acf78a343d19',false); set role authenticated;
insert into r(label,val) select 'payment request generated', public.generate_invoices((date_trunc('month', now()) - interval '1 month')::date)::text;
insert into r(label,val) select 'request amount', 'fees '||fees_minor||', total '||total_minor||', status '||status from invoices where store_org_id='9f589a3a-4a03-4b70-a8e4-921ba175d11d';
insert into r(label,val) select 'rewards before payment', (select count(*) from json_array_elements((public.my_wallet())::json->'activities'))::text||' activities, no rewards yet';
insert into r(label,val) select 'mark paid → rewards', public.mark_invoice_paid((select id from invoices where store_org_id='9f589a3a-4a03-4b70-a8e4-921ba175d11d'),'TEST-ONLY')::text;
reset role;
insert into r(label,val) select 'referrer reward', o.name||' = '||sum(rr.amount_minor)||' (share '||max(rr.share_bps)||'bps)' from referral_rewards rr join organizations o on o.id=rr.referrer_org_id group by o.name;
-- refund after payment → reward reversal
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p6','occurred_at',now()::text,'order',jsonb_build_object('id','PILOT-L','status','refunded','currency','ILS','total',23600,'tax',0,'shipping',0,'shipping_tax',0,'coupons','[]'::jsonb,'refunds',jsonb_build_array(jsonb_build_object('id','rfL','amount',23600)),'ref','','email_hash','','created_at',now()::text)));
select public.approve_matured_commissions();
insert into r(label,val) select 'reward after full refund of link sale', o.name||' = '||sum(rr.amount_minor) from referral_rewards rr join organizations o on o.id=rr.referrer_org_id group by o.name;
-- owner view
select set_config('request.jwt.claim.sub','737ca9c9-fc97-446b-a65c-acf78a343d19',false); set role authenticated;
insert into r(label,val) select 'owner: partner balances', string_agg(x->>'other_name'||' approved_unpaid='||(x->>'approved_unpaid_minor'), '; ') from json_array_elements(public.payout_balances('9f589a3a-4a03-4b70-a8e4-921ba175d11d')) x;
insert into r(label,val) select 'owner: payout recorded', (public.record_creator_payout('9f589a3a-4a03-4b70-a8e4-921ba175d11d',(select v::uuid from ids where k='creator'),'bit','TEST')->>'amount_minor');
do $$ begin perform public.record_creator_payout('9f589a3a-4a03-4b70-a8e4-921ba175d11d',(select v::uuid from ids where k='creator'),'bit','x'); insert into r(label,val) values ('double payout blocked','FAIL'); exception when others then insert into r(label,val) values ('double payout blocked',sqlerrm); end $$;
insert into r(label,val) select 'owner: invite staff', case when public.invite_team_member('9f589a3a-4a03-4b70-a8e4-921ba175d11d','staff@heleni.test','member')->>'token' ~ '^[0-9a-f]{32}$' then 'link created' else 'FAIL' end;
insert into ids values ('tok', (select token from team_invites order by created_at desc limit 1));
insert into r(label,val) select 'LINKUP LAUNCH created', (public.create_campaign('9f589a3a-4a03-4b70-a8e4-921ba175d11d','מבצע בדיקה',null,2000,now()-interval '1 minute',now()+interval '7 days') is not null)::text;
reset role;
select public.ingest_order_event('100432dd-d061-4aa7-8eab-565f20f53edf', jsonb_build_object('event_id','p7','occurred_at',now()::text,'order',jsonb_build_object('id','PILOT-3','status','processing','currency','ILS','total',11800,'tax',0,'shipping',0,'shipping_tax',0,'coupons',jsonb_build_array((select v from ids where k='code')),'refunds','[]'::jsonb,'ref','','email_hash','','created_at',now()::text)));
insert into r(label,val) select 'campaign order commission', a.commission_bps||'bps → creator '||(select sum(amount_minor) from commission_ledger where attribution_id=a.id and party_role='creator') from attributions a join orders o on o.id=a.order_id where o.external_order_id='PILOT-3';
-- staff view
select set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000003',false); set role authenticated;
select public.accept_team_invite((select v from ids where k='tok'));
insert into r(label,val) select 'staff: money visible?', (select count(*) from commission_ledger)||' ledger rows, '||(select count(*) from invoices)||' invoices, dash keys: '||coalesce((public.org_dashboard('9f589a3a-4a03-4b70-a8e4-921ba175d11d')::jsonb ? 'approved_commissions_minor')::text,'');
reset role;
-- creator view + isolation
select set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000001',false); set role authenticated;
insert into r(label,val) select 'creator dashboard', 'approved='||(d->>'approved_minor')||' pending='||(d->>'pending_minor')||' stores='||(d->>'active_stores') from (select public.org_dashboard((select v::uuid from ids where k='creator'))::jsonb d) x;
insert into r(label,val) select 'creator payout to confirm', (public.org_status((select v::uuid from ids where k='creator'))->>'payouts_to_confirm');
insert into r(label,val) select 'creator sees other ledgers/orders', (select count(*) from commission_ledger where party_org_id is distinct from (select v::uuid from ids where k='creator'))||' / '||(select count(*) from orders);
reset role;
select set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000002',false); set role authenticated;
insert into r(label,val) select 'referrer wallet', 'balance='||(a->>'balance_minor')||', referral state='||(select x->>'state' from json_array_elements((public.my_wallet())::json->'referrals') x limit 1) from json_array_elements((public.my_wallet())::json->'activities') a;
reset role;
select step||'. '||label||': '||val from r order by step;
